<template>
<div class="app-container">
  <el-form :inline="true"><el-form-item label="课题"><el-select v-model="topicId" filterable style="width:360px" @change="reload"><el-option v-for="t in topics" :key="t.topicId" :label="t.topicName" :value="t.topicId"/></el-select></el-form-item></el-form>
  <el-row v-if="overview" :gutter="12" class="mb8"><el-col :span="6"><el-card>计划使用<br><b>{{money(overview.plannedUse)}}</b></el-card></el-col><el-col :span="6"><el-card>实际使用<br><b>{{money(overview.actualUse)}}</b></el-card></el-col><el-col :span="6"><el-card>计划剩余<br><b>{{money(overview.remainingUse)}}</b></el-card></el-col><el-col :span="6"><el-card>超计划金额<br><b>{{money(overview.overspend)}}</b></el-card></el-col></el-row>
  <el-button class="mb8" type="primary" plain size="mini" icon="el-icon-plus" :disabled="!topicId" v-hasPermi="['fund:use:add']" @click="openPlan()">新增使用计划</el-button>
  <el-table v-loading="loading" :data="plans">
    <el-table-column label="使用名称" prop="useName" min-width="160"/><el-table-column label="计划金额" width="125"><template slot-scope="s">{{money(s.row.planAmount)}}</template></el-table-column><el-table-column label="实际使用" width="125"><template slot-scope="s">{{money(s.row.actualAmount)}}</template></el-table-column><el-table-column label="剩余金额" width="125"><template slot-scope="s">{{money(remaining(s.row))}}</template></el-table-column><el-table-column label="超支金额" width="125"><template slot-scope="s">{{money(overspend(s.row))}}</template></el-table-column>
    <el-table-column label="执行结果" width="130"><template slot-scope="s"><el-tag :type="resultType(s.row)">{{resultText(s.row)}}</el-tag></template></el-table-column><el-table-column label="责任人" prop="responsibleUserName" width="110"/><el-table-column label="结束原因" prop="finishReason" min-width="160" show-overflow-tooltip/><el-table-column label="完成时间" prop="finishTime" width="165"/>
    <el-table-column label="操作" fixed="right" width="330"><template slot-scope="s"><div class="business-table-actions"><el-button type="text" @click="openRecords(s.row)">使用记录</el-button><el-button type="text" @click="showHistory('USE_PLAN',s.row.usePlanId)">操作历史</el-button><el-button v-if="s.row.status==='0'" type="text" v-hasPermi="['fund:use:edit']" @click="openPlan(s.row)">编辑</el-button><el-button v-if="s.row.status==='0'&&pendingConfirm(s.row)" type="text" v-hasPermi="['fund:use:finish']" @click="confirmFinish(s.row)">确认强制结束</el-button><el-button v-else-if="s.row.status==='0'" type="text" v-hasPermi="['fund:use:finish']" @click="finishPlan(s.row)">结束</el-button></div></template></el-table-column>
  </el-table><pagination v-show="total>0" :total="total" :page.sync="query.pageNum" :limit.sync="query.pageSize" @pagination="loadPlans"/>

  <el-dialog :title="planForm.usePlanId?'编辑使用计划':'新增使用计划'" :visible.sync="planOpen" width="620px"><el-form ref="planForm" :model="planForm" :rules="planRules" label-width="100px"><el-form-item label="使用名称" prop="useName"><el-input v-model="planForm.useName"/></el-form-item><el-form-item label="使用金额" prop="planAmount"><el-input-number v-model="planForm.planAmount" :min="0.01" :precision="2" :step="10000" style="width:100%"/></el-form-item><el-form-item label="责任人"><el-select v-model="planForm.responsibleUserId" clearable filterable style="width:100%"><el-option v-for="u in topicUsers" :key="u.userId" :label="u.nickName||u.userName" :value="u.userId"/></el-select></el-form-item><el-form-item label="计划时间"><el-date-picker v-model="planForm.planTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input v-model="planForm.fundDesc" type="textarea"/></el-form-item></el-form><div slot="footer"><el-button @click="planOpen=false">取消</el-button><el-button type="primary" @click="savePlan">确定</el-button></div></el-dialog>
  <el-dialog :title="recordPlan.useName+' - 使用记录'" :visible.sync="recordsOpen" width="1000px"><el-button v-if="recordPlan.status==='0'&&!pendingConfirm(recordPlan)" type="primary" plain size="mini" v-hasPermi="['fund:use:submit']" @click="openRecord()">提交使用</el-button><el-table :data="records"><el-table-column label="名称" prop="useName"/><el-table-column label="金额" width="120"><template slot-scope="s">{{money(s.row.amount)}}</template></el-table-column><el-table-column label="提交人" prop="submitUserName" width="110"/><el-table-column label="时间" prop="useTime" width="165"/><el-table-column label="附件" min-width="180"><template slot-scope="s"><el-button v-for="a in s.row.attachments||[]" :key="a.attachmentId" type="text" @click="downloadAttachment(a)">{{a.originalName}}</el-button><span v-if="!s.row.attachments||!s.row.attachments.length">-</span></template></el-table-column><el-table-column label="操作" width="170"><template slot-scope="s"><div class="business-table-actions"><el-button type="text" @click="showHistory('USE_RECORD',s.row.useRecordId)">历史</el-button><el-button v-if="recordPlan.status==='0'&&!pendingConfirm(recordPlan)" type="text" @click="openRecord(s.row)">编辑</el-button><el-button v-if="recordPlan.status==='0'&&!pendingConfirm(recordPlan)" type="text" @click="deleteRecord(s.row)">删除</el-button></div></template></el-table-column></el-table></el-dialog>
  <el-dialog title="使用记录" :visible.sync="recordOpen" width="620px"><el-form ref="recordForm" :model="recordForm" :rules="recordRules" label-width="100px"><el-form-item label="使用名称" prop="useName"><el-input v-model="recordForm.useName"/></el-form-item><el-form-item label="使用金额" prop="amount"><el-input-number v-model="recordForm.amount" :min="0.01" :precision="2" style="width:100%"/></el-form-item><el-form-item label="使用时间" prop="useTime"><el-date-picker v-model="recordForm.useTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" style="width:100%"/></el-form-item><el-form-item label="资金说明"><el-input v-model="recordForm.fundDesc" type="textarea"/></el-form-item><el-form-item v-if="existingAttachments.length" label="已有附件"><el-button v-for="a in existingAttachments" :key="a.attachmentId" type="text" @click="downloadAttachment(a)">{{a.originalName}}</el-button></el-form-item><el-form-item :label="existingAttachments.length?'新增附件':'使用凭证'"><file-upload v-model="recordForm.voucherUrls" :limit="5" :file-type="allowedFileTypes"/></el-form-item></el-form><div slot="footer"><el-button @click="recordOpen=false">取消</el-button><el-button type="primary" @click="saveRecord">确定</el-button></div></el-dialog>
  <el-dialog title="操作历史" :visible.sync="historyOpen" width="760px"><el-table :data="history"><el-table-column label="操作" width="150"><template slot-scope="s">{{operationText(s.row.operationType)}}</template></el-table-column><el-table-column label="操作人ID" prop="operatorId" width="110"/><el-table-column label="时间" prop="operationTime" width="165"/><el-table-column label="原因" prop="reason" min-width="220" show-overflow-tooltip/></el-table></el-dialog>
</div>
</template>
<script>
import {accessibleGroups,groupMembers} from '@/api/research/group'
import {getUseOverview} from '@/api/fund/budget'
import {listUsePlans,addUsePlan,updateUsePlan,listUseRecords,addUseRecord,updateUseRecord,delUseRecord,useFinishCheck,finishUse,confirmForceFinish} from '@/api/fund/use'
import {downloadFundAttachment} from '@/api/fund/attachment'
import {listFundOperationLogs} from '@/api/fund/operationLog'
export default{name:'FundUse',data(){return{topics:[],topicId:null,overview:null,plans:[],loading:false,total:0,query:{pageNum:1,pageSize:10},topicUsers:[],planOpen:false,planForm:{},recordsOpen:false,recordPlan:{},records:[],recordOpen:false,recordForm:{},existingAttachments:[],historyOpen:false,history:[],allowedFileTypes:['pdf','doc','docx','xls','xlsx','jpg','jpeg','png'],planRules:{useName:[{required:true,message:'请输入使用名称'}],planAmount:[{required:true,message:'请输入金额'}]},recordRules:{useName:[{required:true,message:'请输入名称'}],amount:[{required:true,message:'请输入金额'}],useTime:[{required:true,message:'请选择时间'}]}}},created(){accessibleGroups().then(r=>{this.topics=(r.data||[]).map(g=>({topicId:g.groupId,topicName:g.groupName}));if(this.topics.length){this.topicId=this.topics[0].topicId;this.reload()}})},methods:{money(v){return Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2})},remaining(r){return Math.max(Number(r.planAmount||0)-Number(r.actualAmount||0),0)},overspend(r){return Math.max(Number(r.actualAmount||0)-Number(r.planAmount||0),0)},pendingConfirm(r){return r.status==='0'&&r.forceFinish==='1'&&r.finishType==='2'&&!r.confirmUserId},resultText(r){if(this.pendingConfirm(r))return'待负责人确认';if(r.status!=='1')return'执行中';return{'0':'按计划完成','1':'低于计划','2':'强制结束'}[r.finishType]||'已结束'},resultType(r){if(this.pendingConfirm(r))return'warning';return r.status!=='1'?'info':(r.finishType==='0'?'success':'warning')},operationText(t){return{CREATE_PLAN:'创建计划',UPDATE_PLAN:'修改计划',CHANGE_PLAN_AMOUNT:'变更计划金额',ASSIGN_RESPONSIBLE:'指定责任人',CHANGE_RESPONSIBLE:'变更责任人',CREATE_RECORD:'创建记录',UPDATE_RECORD:'修改记录',DELETE_RECORD:'删除记录',CLOSE_USE:'结束使用',FORCE_CLOSE_USE:'强制结束使用'}[t]||t},reload(){this.loadPlans();this.loadTopicUsers();getUseOverview(this.topicId).then(r=>{this.overview=r.data}).catch(()=>{this.overview=null})},loadPlans(){if(!this.topicId)return;this.loading=true;listUsePlans(Object.assign({},this.query,{topicId:this.topicId})).then(r=>{this.plans=r.rows;this.total=r.total}).finally(()=>{this.loading=false})},loadTopicUsers(){groupMembers(this.topicId).then(r=>{this.topicUsers=r.data||[]})},openPlan(r){this.planForm=r?Object.assign({},r):{topicId:this.topicId,useName:'',planAmount:0,responsibleUserId:null,planTime:null,fundDesc:''};this.planOpen=true},savePlan(){this.$refs.planForm.validate(ok=>{if(!ok)return;(this.planForm.usePlanId?updateUsePlan:addUsePlan)(this.planForm).then(()=>{this.$modal.msgSuccess('保存成功');this.planOpen=false;this.reload()})})},openRecords(r){this.recordPlan=r;listUseRecords(r.usePlanId).then(x=>{this.records=x.data||[];this.recordsOpen=true})},openRecord(r){this.existingAttachments=r&&r.attachments?r.attachments:[];this.recordForm=r?Object.assign({},r,{voucherUrls:null,attachments:undefined}):{usePlanId:this.recordPlan.usePlanId,useName:'',amount:0,useTime:null,fundDesc:'',voucherUrls:''};this.recordOpen=true},saveRecord(){this.$refs.recordForm.validate(ok=>{if(!ok)return;(this.recordForm.useRecordId?updateUseRecord:addUseRecord)(this.recordForm).then(()=>{this.$modal.msgSuccess('保存成功');this.recordOpen=false;this.openRecords(this.recordPlan);this.reload()})})},deleteRecord(r){this.$modal.confirm('确认删除该使用记录？').then(()=>delUseRecord(r.useRecordId)).then(()=>{this.openRecords(this.recordPlan);this.reload()})},downloadAttachment(a){downloadFundAttachment(a.attachmentId,a.originalName)},showHistory(businessType,businessId){listFundOperationLogs({groupId:this.topicId,businessType,businessId}).then(r=>{this.history=r.data||[];this.historyOpen=true})},confirmFinish(r){this.$modal.confirm('确认该超支使用计划强制结束？').then(()=>confirmForceFinish(r.usePlanId)).then(()=>{this.$modal.msgSuccess('已确认强制结束');this.reload()})},finishPlan(row){useFinishCheck(row.usePlanId).then(r=>{const c=r.data;if(!c.needConfirm)return this.$modal.confirm('实际金额与计划一致，确认结束？').then(()=>finishUse(row.usePlanId,false,null));const text=c.differenceAmount<0?'实际使用低于计划，请填写结束原因':'实际使用超出计划，请填写强制结束原因';return this.$prompt(text,'差异确认',{inputType:'textarea',inputValidator:v=>!!(v&&v.trim())||'结束原因必填'}).then(({value})=>finishUse(row.usePlanId,true,value.trim()))}).then(x=>{if(x){this.$modal.msgSuccess('结束操作已提交');this.reload()}})}}}
</script>
